KK3ImXbwaU0z\nTm3eJLFO0LFNW0Tkm2f2GUxV5kaH5aW969D1Q0+310oxh3QRkYxDGSLyhxNE5Nz+4Q8k/dQ+\nxHxix5i9mQWuwdTdP4vI4OuqlS6p0d1tSi/aQqrmfL978dxHR941qEeXG+qGha08felDdQ2H\nzDVo2rJnj4jI+a8mJecU9lwyqKLuLADwTiZPFwDATdrMiHFufXnBz5m3LNlvqz4k0mrqe1eD\nefOXpRY+/uKHp0Mazanpb8gy+ItIi0lrnupW+7Kbm4Nbi4j84QQR3ak9sf3QPSFrwtvPGhS3\n6sS/x4qIwWQQEYP2q5sYLKGlF998uPuAxR9FtOnWO6bD7R1veXhOq1OjeoxNLdl+zEN1Ap9f\n/aTM3/x+4laTud7SzjXL444BAIV4+r1gAG5SlH8i0GhoMfG/w8IDGg38SNf1iz9OE5FxB3YZ\nNK3zmqO6rhfmfmfUtKhRe0rfsDAnecOGDR+fyb6aCc1sfjVv2OYaX3V7PRF5dM9ZXdfP7hsk\nIv13nih9w+RV/5BfPmOXn/mpUdPq3fZC6QlrmlS1hHS/NP+FTiKy7uR31f2M1/R5u7zuGQBQ\nBsEO8CHzGoVYq91h1LRBn57Rdd1ZdLGqn6FWj6YisvVC8ckQc6PDTNZr3z+TXXKrpLubaJqW\nlJJ9NRMunRWr6wX2L+pbTNawnhcKHUW5P4b7GwNr9z+SVeham3/xQJcQS0mwyz77soi0nvZF\nyWazT++JDvCzhHQrGcm/+IlR0yJuixSR2d+lV8A9BADejWAH+JDDyzu4DtV//svJpPMbhYiI\nNez2kjn2YxvrmU1+tgYD7xm/YP7su3o0E5EWI9Zd5YTSwU7X9eQXeovI9dN267r+1dIBImKt\n3m5U4vTpife1DrU0uOWekmCnO3Jjw6xG/5oPPLZozUsrpyfG17SGdGwQZDCFPPvqpiyH07XB\nifWqiIglpJujYu8qAPBKBDvAh2SnrBORkguI6Lr+1fx2ItIkYVfpaReP7ri/X5eaIYH+tqqR\nrTvNevHdQqd+lRMuC3a6s2Bko2CDqcrWlBxd1z977fGYNg0DzaaganXvfGC5PesbKXW5k6zj\n7yfcckNEWECVmg273jb8ncNp575YeE2ozT+w+sn84mugHFnVSURaTf28vO8bAFCBpuu6+z7Q\nBwB/zxePtm7/5MG3zuX0LXW9FQCAC8EOgNdwFp6/MSziSOjYjGNPe7oWAKiMuNwJAO8wZtzD\nOd9t+a+94N4tEzxdCwBUUhyxA+AdosODfioKjhu7JGlOnKdrAYBKimAHAACgCL5SDAAAQBEE\nOwAAAEUQ7AAAABRBsAMAAFAEwQ4AAEARBDsAAABFEOwAAAAUQbADAABQBMEOAABAEf8Po4ws\niUullYUAAAAASUVORK5CYII="},"metadata":{"image/png":{"height":420,"width":420}},"output_type":"display_data"}],"source":["library(tidyverse) #helps wrangle data\n","# Use the conflicted package to manage conflicts\n","library(conflicted)\n","# Set dplyr::filter and dplyr::lag as the default choices\n","conflict_prefer(\"filter\", \"dplyr\")\n","conflict_prefer(\"lag\", \"dplyr\")\n","#=====================\n","# STEP 1: COLLECT DATA\n","#=====================\n","# # Upload Divvy datasets (csv files) here\n","q1_2019 <- read_csv(\"/kaggle/input/divvy-trips-sample-dataset/Divvy_Trips_2019_Q1_csv_version.csv\")\n","q1_2020 <- read_csv(\"/kaggle/input/divvy-trips-sample-dataset/Divvy_Trips_2020_Q1_csv_version.csv\")\n","\n","problems(q1_2019)\n","problems(q1_2020)\n","\n","#====================================================\n","# STEP 2: WRANGLE DATA AND COMBINE INTO A SINGLE FILE\n","#====================================================\n","# Compare column names in each of the files\n","# While the names don't have to be in the same order, they DO need to match perfectly before we can use a command to join them into one file\n","colnames(q1_2019)\n","colnames(q1_2020)\n","# Rename columns to make them consistent with q1_2020 (as this will be the supposed going-forward table design for Divvy)\n","(q1_2019 <- rename(q1_2019\n","                   ,ride_id = trip_id\n","                   ,rideable_type = bikeid\n","                   ,started_at = start_time\n","                   ,ended_at = end_time\n","                   ,start_station_name = from_station_name\n","                   ,start_station_id = from_station_id\n","                   ,end_station_name = to_station_name\n","                   ,end_station_id = to_station_id\n","                   ,member_casual = usertype)\n",")\n","\n","# Inspect the dataframes and look for incongruencies\n","str(q1_2019)\n","str(q1_2020)\n","\n","# Convert ride_id and rideable_type to character so that they can stack correctly\n","q1_2019 <- mutate(q1_2019, ride_id = as.character(ride_id)\n","                  ,rideable_type = as.character(rideable_type))\n","\n","# Function to convert \"HHH:MM:SS\" to seconds\n","convert_to_seconds <- function(time_str) {\n","  parts <- strsplit(time_str, \":\")\n","  sapply(parts, function(x) {\n","    as.numeric(x[1]) * 3600 + as.numeric(x[2]) * 60 + as.numeric(x[3])\n","  })\n","}\n","\n","# Apply to q1_2019\n","q1_2019$ride_length <- convert_to_seconds(q1_2019$ride_length)\n","\n","# Also apply to q1_2020 \n","if (!is.numeric(q1_2020$ride_length)) {\n","  q1_2020$ride_length <- as.numeric(q1_2020$ride_length)\n","}\n","\n","# Stack individual quarters' data frames into one big data frame\n","all_trips <- bind_rows(q1_2019, q1_2020)#, q3_2019)#, q4_2019, q1_2020)\n","# Remove lat, long, birthyear, and gender fields, as this data was dropped beginning in 2020\n","all_trips <- all_trips %>%\n","  select(-c(start_lat, start_lng, end_lat, end_lng, birthyear, gender, \"tripduration\"))\n","\n","# STEP 3: CLEAN UP AND ADD DATA TO PREPARE FOR ANALYSIS\n","#======================================================\n","# Inspect the new table that has been created\n","colnames(all_trips) #List of column names\n","nrow(all_trips) #How many rows are in data frame?\n","dim(all_trips) #Dimensions of the data frame?\n","head(all_trips) #See the first 6 rows of the data frame. Also tail(all_trips)\n","str(all_trips) #See list of columns and data types (numeric, character, etc)\n","summary(all_trips) #Statistical summary of data. Mainly for numerics\n","# There are a few problems we will need to fix:\n","# (1) In the \"member_casual\" column, there are two names for members (\"member\" and \"Subscriber\") and two names for casual riders (\"Customer\" and \"casual\"). We will need to consolidate that from four to two labels.\n","# (2) The data can only be aggregated at the ride-level, which is too granular. We will want to add some additional columns of data -- such as day, month, year -- that provide additional opportunities to aggregate the data.\n","# (3) We will want to add a calculated field for length of ride since the 2020Q1 data did not have the \"tripduration\" column. We will add \"ride_length\" to the entire dataframe for consistency.\n","# (4) There are some rides where tripduration shows up as negative, including several hundred rides where Divvy took bikes out of circulation for Quality Control reasons. We will want to delete these rides.\n","# In the \"member_casual\" column, replace \"Subscriber\" with \"member\" and \"Customer\" with \"casual\".\n","# Before 2020, Divvy used different labels for these two types of riders ... we will want to make our dataframe consistent with their current nomenclature\n","# N.B.: \"Level\" is a special property of a column that is retained even if a subset does not contain any values from a specific level\n","# Begin by seeing how many observations fall under each usertype table(all_trips$member_casual)\n","# Reassign to the desired values (we will go with the current 2020 labels)\n","all_trips <- all_trips %>%\n","  mutate(member_casual = recode(member_casual\n","                                ,\"Subscriber\" = \"member\"\n","                                ,\"Customer\" = \"casual\"))\n","\n","# Check to make sure the proper number of observations was reassigned to the table(all_trips$member_casual)\n","# Add columns that list the date, month, day, and year of each ride\n","# This will allow us to aggregate ride data for each month, day, or year ... before completing these operations we could only aggregate at the ride level\n","all_trips$date <- as.Date(all_trips$started_at) #The default format is yyyy-mm-dd\n","all_trips$month <- format(as.Date(all_trips$date), \"%m\")\n","all_trips$day <- format(as.Date(all_trips$date), \"%d\")\n","all_trips$year <- format(as.Date(all_trips$date), \"%Y\")\n","all_trips$day_of_week <- format(as.Date(all_trips$date), \"%A\")\n","\n","# Convert datetime values to the right format\n","all_trips$started_at <- as.POSIXct(all_trips$started_at, format = \"%m/%d/%Y %H:%M\")\n","all_trips$ended_at   <- as.POSIXct(all_trips$ended_at, format = \"%m/%d/%Y %H:%M\")\n","\n","# Add a \"ride_length\" calculation to all_trips (in seconds)\n","# https://stat.ethz.ch/R-manual/R-devel/library/base/html/difftime.html\n","all_trips$ride_length <- difftime(all_trips$ended_at,all_trips$started_at)\n","\n","# Inspect the structure of the columns\n","str(all_trips)\n","# Convert \"ride_length\" from Factor to numeric so we can run calculations on the data\n","is.factor(all_trips$ride_length)\n","all_trips$ride_length <- as.numeric(as.character(all_trips$ride_length))\n","is.numeric(all_trips$ride_length)\n","# Remove \"bad\" data\n","# The dataframe includes a few hundred entries when bikes were taken out of the docks and checked for quality by Divvy or ride_length was negative\n","\n","# We will create a new version of the dataframe (v2) since data is being removed\n","all_trips_v2 <- all_trips[!(all_trips$start_station_name == \"HQ QR\" | all_trips$ride_length<0),]\n","\n","# STEP 4: CONDUCT DESCRIPTIVE ANALYSIS\n","#=====================================\n","# Descriptive analysis on ride_length (all figures in seconds)\n","mean(all_trips_v2$ride_length) #straight average (total ride length/rides)\n","median(all_trips_v2$ride_length) #midpoint number in the ascending array of ride lengths\n","max(all_trips_v2$ride_length) #longest ride\n","min(all_trips_v2$ride_length) #shortest ride\n","# You can condense the four lines above to one line using summary() on the specific attribute\n","summary(all_trips_v2$ride_length)\n","# Compare members and casual users\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual, FUN = mean)\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual, FUN = median)\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual, FUN = max)\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual, FUN = min)\n","# See the average ride time by each day for members vs casual users\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual + all_trips_v2$day_of_week,\n","          FUN = mean)\n","# Notice that the days of the week are out of order. Let's fix that.\n","all_trips_v2$day_of_week <- ordered(all_trips_v2$day_of_week, levels=c(\"Sunday\", \"Monday\",\n","                                                                       \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\"))\n","\n","# Now, let's run the average ride time by each day for members vs casual users\n","aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual + all_trips_v2$day_of_week,\n","          FUN = mean)\n","# analyze ridership data by type and weekday\n","all_trips_v2 %>%\n","  mutate(weekday = wday(started_at, label = TRUE)) %>% #creates weekday field using wday()\n","group_by(member_casual, weekday) %>% #groups by usertype and weekday\n","  summarise(number_of_rides = n() #calculates the number of rides and average duration\n","            ,average_duration = mean(ride_length)) %>% # calculates the average duration\n","arrange(member_casual, weekday) # sorts\n","\n","# Override override the grouping behavior by adding .groups = \"drop\" inside summarise()\n","all_trips %>%\n","  group_by(member_casual) %>%\n","  summarise(\n","    avg_ride_length = mean(ride_length),\n","    max_ride_length = max(ride_length),\n","    min_ride_length = min(ride_length),\n","    .groups = \"drop\"\n","  )\n","\n","# Let's visualize the number of rides by rider type\n","all_trips_v2 %>%\n","  mutate(weekday = wday(started_at, label = TRUE)) %>%\n","  group_by(member_casual, weekday) %>%\n","  \n","  summarise(number_of_rides = n()\n","            ,average_duration = mean(ride_length)) %>%\n","  arrange(member_casual, weekday) %>%\n","  ggplot(aes(x = weekday, y = number_of_rides, fill = member_casual)) +\n","  geom_col(position = \"dodge\")\n","\n","# Let's create a visualization for average duration\n","all_trips_v2 %>%\n","  mutate(weekday = wday(started_at, label = TRUE)) %>%\n","  group_by(member_casual, weekday) %>%\n","  summarise(number_of_rides = n()\n","            ,average_duration = mean(ride_length)) %>%\n","  arrange(member_casual, weekday) %>%\n","  ggplot(aes(x = weekday, y = average_duration, fill = member_casual)) +\n","  geom_col(position = \"dodge\")\n","\n","# STEP 5: EXPORT SUMMARY FILE FOR FURTHER ANALYSIS\n","#=================================================\n","# Create a csv file that we will visualize in Excel, Tableau, or my presentation software\n","  counts <- aggregate(all_trips_v2$ride_length ~ all_trips_v2$member_casual +\n","                        all_trips_v2$day_of_week, FUN = mean)\n","   write.csv(counts, file = 'avg_ride_length.csv')"]},{"attachments":{"47b73389-11a8-4281-80bd-dfa1964dad31.png":{"image/png":""},"67f80dd3-37b2-462e-bf8f-b0536149a8df.png":{"image/png":""}},"cell_type":"markdown","id":"1dcac7c7","metadata":{"papermill":{"duration":0.010797,"end_time":"2025-06-22T20:07:46.840469","exception":false,"start_time":"2025-06-22T20:07:46.829672","status":"completed"},"tags":[]},"source":["Case Study: How does a bike-share navigate speedy success\n","\n","Business Task: \n","Cyclistic, a Chicago-based bike-share company, aims to increase annual memberships to ensure long-term revenue growth. The marketing team needs data insights to understand the differences in behavior between casual riders and annual members. These insights will help design a targeted marketing strategy to convert casual riders into annual members.\n","\n","Key Questions to Answer:\n","How do annual members and casual riders use Cyclistic bikes differently?\n","Why would casual riders buy Cyclistic annual memberships?\n","How can Cyclistic use digital media to influence casual riders to become members?\n","\n","Data Sources Used\n","Dataset: Public dataset Divvy_2019_Q1 and Divvy 2020_Q1, which have been made available by Motive International Inc. under a Bikeshare license. \n","\n","Period Analyzed: 2019 - 2020\n","\n","Data Fields:\n","ride_id, rideable_type, started_at, ended_at\n","start_station_name, end_station_name, member_casual\n","day_of_week, trip_duration (calculated)\n","\n","Step 1: WRANGLE DATA AND COMBINE INTO A SINGLE FILE\n","   \n","   Compare column names in  each of the files\n","NB:   While the names don't have to be in the same order, they do need to match perfectly before the command can be used to join them together in a single file.\n","   \n","   Rename column in the 2019 dataset to make them consistent with the 2020 dataset (as this will be the supposed going forward table design for Divvy.\n","   \n","   Inspect the dataframes and look for inconsistencies\n","   \n","   Convert ride_id and rideable_type to character so that they can stack correctly\n","   \n","   Stack individual quarters'data frames into one big data frame\n","   \n","   Remove lat, long, birthyear, and gender field, as this data was dropped beginning in 2020\n","\n","STEP 2: Data Cleaning and Manipulation performed in R and Excel   \n","   \n","   Inspect the new table that has been created:\n","   \n","   List of column names\n","   \n","   How many rows are in the data frame?\n","   \n","   Dimensions of the data frame?\n","   \n","   See the first 6 rows of the data frame. Also tail(all_trips)\n","   \n","   See the list of columns and data types\n","   \n","   Statistical summary of data\n","\n","NB: A Few problems were fixed:\n","    \n","    1. In the \"member_casual\" column, there are two names for members (\"member\" and \"Subscriber\") and two names for casual riders (\"Customer\" and \"casual\"). I consolidated that from four to two labels.\n","    \n","    2. The data can only be aggregated at the ride level, which is too granular. Added some additional columns of data, such as day, month,and year, which provided additional opportunities to aggregate the data.\n","    \n","    3. I added a calculated field for the length of ride since the 2020Q1 data did not have the \"tripduration\" column. Added \"ride_length\" to the entire dataframe for consistency.\n","    \n","    4. There are some rides where tripduration shows up as negative, including several hundred rides where Divvy took bikes out of circulation for Quality Control reasons. These rides should be deleted.\n","   \n","   In the \"member_casual\" column, replace \"Subscriber\" with \"member\" and \"Customer\" with\"casual\"\n","   \n","   Before 2020, Divvy used different labels for these two types of riders, but made the dataframe consistent with their current nomenclature.\n","\n","NB: \"Level\" is a special property of a column that is retained even if a subset does not contain any values from a specific level\n","   \n","   Begin by seeing how many observations fall under each usertype\n","   \n","   Reassign to the desired values\n","   \n","   Check to make sure the proper number of observations were reassigned\n","   \n","   Add columns that list the date, month, day, and year of each ride. This allowed me to aggregate ride data for each month, day, or year ... before completing these operations, I could only aggregate at the ride level\n","   \n","   Add a \"ride_length\" calculation to all_trips (in seconds)\n","   \n","   Inspect the structure of the columns\n","   \n","   Convert \"ride_length\" from Factor to numeric to allow calculations on the data\n","   \n","   Remove \"bad\" data\n","\n","The dataframe includes a few hundred entries when bikes were taken out of the docks and checked for quality by Divvy, or ride_length was negative\n","\n","Create a new version of the dataframe (v2) since data is being removed\n","\n","STEP 3: CONDUCT DESCRIPTIVE ANALYSIS\n","    \n","    Descriptive analysis on ride_length:\n","    straight average (total ride length/rides)\n","    \n","    midpoint number in the ascending array of ride lengths\n","    \n","    longest ride\n","    \n","    shortest ride\n","\n","NB: The four lines above can be condensed to one line using summary() on the specific attribute.\n","    \n","    Compare members and casual users\n","    \n","    See the average ride time by each day for members vs casual users\n","NB: The days of the week are out of order, and it was fixed by using the levels function to reorder the days of the week in the day_of_week column.\n","    \n","    Analyze ridership data by type and weekday\n","    \n","    Let's visualize the number of rides by rider type\n","![Visualization for the number of rides by rider type .png](attachment:47b73389-11a8-4281-80bd-dfa1964dad31.png)\n","\n","    visualization for average duration\n","![Visualization for average duration.png](attachment:67f80dd3-37b2-462e-bf8f-b0536149a8df.png)\n","\n","Step 4: Summary Analysis on the average ride length\n","1. How do annual members and casual riders use Cyclistic bikes differently?\n","\n","Summary Report: Average Ride Length by User Type( Annual members and Casual riders)\n","\n","Data Preview\n","member_casual\tride_length\n","casual\t        5370.7474\n","member\t        795.1109\n","\n","| Metric                        | Casual Riders     | Members           |\n","| ----------------------------- | ----------------- | ----------------- |\n","| **Average Ride Length (sec)** | **5,370.75**      | **795.11**        |\n","| **Average Ride Length (min)** | **89.51 minutes** | **13.25 minutes** |\n","| **Ratio (Casual / Member)**   | **6.75x longer**  | —                 |\n","\n","\n","Insights\n","Casual riders have significantly longer ride durations compared to members, about 6.75 times longer.\n","\n","This suggests that:\n","\n","Casual users may use the service more for leisure or recreational purposes.\n","\n","Members may use it for short, routine commutes (e.g., work or errands).\n","\n","Recommendations\n","Target casual riders with membership promotions that emphasize:\n","\n","Cost savings for frequent use.\n","\n","Added convenience for daily commuting.\n","\n","Consider segmenting marketing campaigns by trip duration patterns to nudge longer-term commitment.\n","\n","\n","Weekly Patterns:\n","\n","Casual riders' ride duration peaks during weekends, reinforcing recreational usage.\n","\n","Members maintain consistent short-duration usage throughout the week, typical of daily commuting behavior.\n","\n","2. Why would casual riders buy Cyclistic annual memberships?\n","\n","Cost savings: Frequent casual riders with longer durations can save money on per-ride fees by becoming members.\n","\n","Convenience: Membership likely includes faster checkout, priority access, or unlimited short rides, ideal for locals or repeat visitors.\n","\n","Incentives: Personalized offers, loyalty points, or discounted renewals could encourage the transition.\n","\n","3. How can Cyclistic use digital media to influence casual riders to become members?\n","\n","Targeted Campaigns:\n","\n","Use data to target frequent casual users with personalized ads showing how much they'd save as members.\n","\n","Use weekend-only membership ads tailored to casual riders who mostly ride on weekends.\n","\n","Engaging Content:\n","\n","Run social media stories featuring members who switched from casual usage, highlighting convenience and savings.\n","\n","Use interactive cost-saving calculators on the website and in mobile app prompts.\n","\n","Promotions:\n","\n","Free trial weekends or discounted first-month memberships are promoted via email and Instagram/Facebook.\n","\n","Recommendations\n","Segment & Target: Identify casual users with ride frequency >4/month and target them with upgrade incentives.\n","\n","Tailored Messaging: Highlight convenience and cost savings for common use cases like weekend rides or commute coverage.\n","\n","Campaign Channels:\n","\n","Social: Instagram reels showing the ease of being a member.\n","\n","Email: Ride summary + \"You could’ve saved $X as a member!\"\n","\n","App: In-app prompt offering a free 3-day trial or weekend pass with a one-click upgrade."]},{"cell_type":"markdown","id":"0fda63bd","metadata":{"papermill":{"duration":0.010498,"end_time":"2025-06-22T20:07:46.861421","exception":false,"start_time":"2025-06-22T20:07:46.850923","status":"completed"},"tags":[]},"source":["#  Key Insights\n","\n","- **Ride Duration:** Casual riders take significantly longer trips than members.\n","- **Usage Patterns:** Members mostly ride during weekdays (commute behavior), while casual users ride more on weekends.\n","- **Station Popularity:** Certain start and end stations are dominant, indicating commuter and tourist hotspots.\n","\n","# Recommendations\n","\n","- Expand and maintain popular stations, especially those near downtown and tourist locations.\n","- Ensure high bike availability during weekday rush hours.\n","- Develop targeted campaigns to convert casual riders to members.\n","\n","\n"]}],"metadata":{"kaggle":{"accelerator":"none","dataSources":[{"datasetId":7589943,"sourceId":12059010,"sourceType":"datasetVersion"}],"dockerImageVersionId":30749,"isGpuEnabled":false,"isInternetEnabled":true,"language":"r","sourceType":"notebook"},"kernelspec":{"display_name":"R","language":"R","name":"ir"},"language_info":{"codemirror_mode":"r","file_extension":".r","mimetype":"text/x-r-source","name":"R","pygments_lexer":"r","version":"4.4.0"},"papermill":{"default_parameters":{},"duration":25.077285,"end_time":"2025-06-22T20:07:46.991712","environment_variables":{},"exception":null,"input_path":"__notebook__.ipynb","output_path":"__notebook__.ipynb","parameters":{},"start_time":"2025-06-22T20:07:21.914427","version":"2.6.0"}},"nbformat":4,"nbformat_minor":5}